let decorSelected=null;
function decorScale(d){return Number.isFinite(d.scale)?Math.max(.4,Math.min(2,d.scale)):1}
function orderedDecor(){return tank().decor.slice().sort((a,b)=>(Number.isFinite(a.layer)?a.layer:a.y)-(Number.isFinite(b.layer)?b.layer:b.y))}
function nextDecorLayer(){return Math.max(0,...tank().decor.map(d=>Number.isFinite(d.layer)?d.layer:d.y))+1}
function moveDecorLayer(d,action){const list=orderedDecor(),i=list.indexOf(d);if(i<0)return;list.splice(i,1);const j=action==='front'?list.length:action==='back'?0:action==='forward'?Math.min(i+1,list.length):Math.max(0,i-1);list.splice(j,0,d);list.forEach((item,index)=>item.layer=index);save();renderDecorEditor()}
function renderDecorEditor(){const panel=$('decorEditor');panel.hidden=!editing;if(!editing)return;const list=orderedDecor();let d=list.find(x=>x.uid===decorSelected);if(!d){d=list[list.length-1];decorSelected=d?.uid||null}panel.innerHTML='<strong>Editar decoraciones</strong><p>Arrastra una pieza en el acuario o elígela aquí, aunque esté detrás de otra.</p><label>Pieza<select id="decorChoice">'+list.map((x,i)=>'<option value="'+x.uid+'">'+deco(x.id).name+' · capa '+(i+1)+'</option>').join('')+'</select></label>'+(d?'<label>Tamaño <output id="decorSizeValue">'+Math.round(decorScale(d)*100)+'%</output><input id="decorSize" type="range" min="40" max="200" step="5" value="'+Math.round(decorScale(d)*100)+'"></label><div class="actions"><button id="decorMirror" aria-pressed="'+!!d.flip+'">↔ Reflejar</button><button id="decorReset">Tamaño original</button></div><div class="actions"><button id="decorBack">Al fondo</button><button id="decorBackward">Una capa atrás</button><button id="decorForward">Una capa delante</button><button id="decorFront">Al frente</button></div><div class="actions"><button id="decorStore">Guardar en almacén</button><button id="decorDone">Terminar</button></div>':'<p>Compra y coloca una decoración para editarla.</p><button id="decorDone">Terminar</button>');if(d){$('decorChoice').value=d.uid;$('decorChoice').onchange=()=>{decorSelected=$('decorChoice').value;renderDecorEditor()};$('decorSize').oninput=()=>{d.scale=Number($('decorSize').value)/100;$('decorSizeValue').textContent=Math.round(d.scale*100)+'%';save()};$('decorMirror').onclick=()=>{d.flip=!d.flip;save();renderDecorEditor()};$('decorReset').onclick=()=>{d.scale=1;save();renderDecorEditor()};for(const [id,action] of [['decorBack','back'],['decorBackward','backward'],['decorForward','forward'],['decorFront','front']])$(id).onclick=()=>moveDecorLayer(d,action);const i=list.indexOf(d);$('decorBack').disabled=$('decorBackward').disabled=i===0;$('decorFront').disabled=$('decorForward').disabled=i===list.length-1;$('decorStore').onclick=()=>{tank().decor=tank().decor.filter(x=>x.uid!==d.uid);state.inventory.push({uid:d.uid,id:d.id,scale:decorScale(d),flip:!!d.flip});decorSelected=null;save();render()}}$('decorDone').onclick=()=>{$('edit').onclick()}}


const SUBSTRATES=[{id:'sand',name:'Arena natural',price:0,colors:['#c6ad7d','#e3cda2','#f2e1b9','#a58d64'],sand:true},{id:'river',name:'Piedras de río',price:120,colors:['#a7a49b','#d2c9b6','#787d77','#bab39f']},{id:'pearl',name:'Piedras perladas',price:160,colors:['#f6efdf','#d7d9d4','#fff9ef','#bfc7c3']},{id:'rose',name:'Piedras rosa',price:180,colors:['#eeb4c5','#cc809c','#f9d4db','#ad6486']},{id:'blue',name:'Piedras turquesa',price:180,colors:['#6dc9d1','#3d939f','#afe8e1','#407e90']},{id:'violet',name:'Piedras violeta',price:180,colors:['#b0a0d4','#8074aa','#d2bde9','#68608e']},{id:'rainbow',name:'Piedras arcoíris',price:250,colors:['#edbc78','#9ec4b0','#a5badd','#e9a9ba','#baa1d0']}];
function substrate(id){return SUBSTRATES.find(x=>x.id===id)||SUBSTRATES[0]}
function ownedSubstrates(){return Array.isArray(state.substrates)?state.substrates:['sand']}
function chooseSubstrate(id){const item=SUBSTRATES.find(x=>x.id===id);if(!item)return;if(!ownedSubstrates().includes(id)){if(!pay(item.price))return;state.substrates=[...ownedSubstrates(),id]}tank().substrate=id;save();render();toast(item.name+' aplicado a este acuario.')}
function renderSubstrateShop(){document.querySelectorAll('#shopTabs button').forEach(b=>b.classList.toggle('active',!$('shopPanel').hidden&&b.dataset.tab===tab));$('shopTitle').textContent='Un fondo a tu gusto';$('shopSubtitle').textContent='Compra una vez y úsalo en todos tus acuarios.';$('shop').replaceChildren();SUBSTRATES.forEach(item=>{const owned=ownedSubstrates().includes(item.id),active=(tank().substrate||'sand')===item.id;const card=document.createElement('div');card.className='card';card.innerHTML='<div class="art substrate-art" aria-hidden="true"></div><div><span class="rarity">'+(owned?'EN TU COLECCIÓN':'SUSTRATO')+'</span><h3>'+item.name+'</h3><p>'+(item.sand?'Grano fino y relieve suave':'Piedras redondeadas con luces y sombras')+'</p><button '+(active?'disabled':'')+'>'+(active?'✓ En este acuario':owned?'Usar en este acuario':'🪙 '+item.price+' · Comprar y usar')+'</button></div>';const preview=card.querySelector('.substrate-art');preview.style.background='linear-gradient(150deg,'+item.colors[1]+','+item.colors[0]+')';for(let i=0;i<24;i++){const pebble=document.createElement('i');pebble.style.cssText='left:'+((i*37)%90)+'%;top:'+((i*23)%85)+'%;background:'+item.colors[i%item.colors.length]+';width:'+(item.sand?3:9+i%5)+'px;height:'+(item.sand?2:6+i%4)+'px;transform:rotate('+(i*29)+'deg)';preview.append(pebble)}card.querySelector('button').onclick=()=>chooseSubstrate(item.id);$('shop').append(card)})}
const substrateCache=new Map();
function paintSubstrate(ctx,W,H,t){const item=substrate(t.substrate),photo=backgroundReady(t);const key=item.id+'-'+W+'-'+H+'-'+photo;let surface=substrateCache.get(key);if(!surface){substrateCache.clear();surface=document.createElement('canvas');surface.width=W;surface.height=H;const c=surface.getContext('2d');let seed=8721;const rand=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296};c.beginPath();c.moveTo(0,H*.89);c.quadraticCurveTo(W*.5,H*.84,W,H*.9);c.lineTo(W,H);c.lineTo(0,H);c.closePath();c.save();c.clip();const base=c.createLinearGradient(0,H*.86,0,H);base.addColorStop(0,item.colors[3]);base.addColorStop(.25,item.colors[0]);base.addColorStop(1,item.colors[1]);c.fillStyle=base;c.fillRect(0,H*.85,W,H*.15);if(item.sand){for(let i=0;i<9;i++){c.strokeStyle=i%2?'#fff6df20':'#71603d18';c.lineWidth=2+i%3;c.beginPath();for(let x=0;x<=W;x+=8){const y=H*(.88+i*.014)+Math.sin(x/90+i)*3;x?c.lineTo(x,y):c.moveTo(x,y)}c.stroke()}for(let i=0;i<W*H*.025;i++){const x=rand()*W,y=H*(.85+rand()*.15),r=.35+rand()*.75;c.fillStyle=item.colors[Math.floor(rand()*item.colors.length)];c.globalAlpha=.3+rand()*.5;c.fillRect(x,y,r*1.5,r)}c.globalAlpha=1}else{for(let row=0;row<16;row++){const depth=row/15,y=H*(.86+.15*depth),size=2+depth*3;for(let x=-10;x<W+10;x+=size*1.9){const px=x+(rand()-.5)*size,py=y+(rand()-.5)*size,rx=size*(.8+rand()*.5),ry=size*(.55+rand()*.3);c.fillStyle='#233d4440';c.beginPath();c.ellipse(px+.8,py+1.2,rx,ry,0,0,7);c.fill();const shine=c.createRadialGradient(px-rx*.3,py-ry*.4,.1,px,py,rx);shine.addColorStop(0,item.colors[1]);shine.addColorStop(.4,item.colors[Math.floor(rand()*item.colors.length)]);shine.addColorStop(1,item.colors[3]);c.fillStyle=shine;c.beginPath();c.ellipse(px,py,rx,ry,rand()*.5,0,7);c.fill();c.fillStyle='#ffffff35';c.beginPath();c.ellipse(px-rx*.2,py-ry*.35,rx*.35,ry*.15,0,0,7);c.fill()}}}c.restore();if(photo){c.globalCompositeOperation='destination-in';const blend=c.createLinearGradient(0,H*.85,0,H);blend.addColorStop(0,'#00000000');blend.addColorStop(.2,'#000000ff');blend.addColorStop(1,'#000000ff');c.fillStyle=blend;c.fillRect(0,0,W,H);c.globalCompositeOperation='source-over'}substrateCache.set(key,surface)}ctx.drawImage(surface,0,0)}
function drawSubstrate(){paintSubstrate(ctx,W,H,tank())}


