const SEASON_IDS=['halloween','christmas','valentines'];
const SEASONS={halloween:{label:'Halloween',icon:'🎃',title:'El arrecife de medianoche',dates:'Del 1 al 31 de octubre',prefix:'hw',missions:HALLOWEEN_MISSIONS},christmas:{label:'Navidad',icon:'🎄',title:'Navidad bajo el mar',dates:'Del 1 al 31 de diciembre',prefix:'xm',missions:CHRISTMAS_MISSIONS},valentines:{label:'Enamorados',icon:'💕',title:'Corazones bajo el mar',dates:'Del 1 al 28 de febrero de 2027',prefix:'vl',missions:VALENTINE_MISSIONS}};
function seasonMissions(id){return SEASONS[id]?.missions||[]}
// Horario de Ciudad de México. Enamorados es exclusivo de febrero de 2027.
function seasonDate(now=Date.now()){const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/Mexico_City',year:'numeric',month:'numeric',day:'numeric'}).formatToParts(new Date(now));return Object.fromEntries(parts.filter(p=>['year','month','day'].includes(p.type)).map(p=>[p.type,Number(p.value)]))}
function seasonOpen(id,now=Date.now()){const d=seasonDate(now);return id==='valentines'?d.year===2027&&d.month===2:id==='halloween'?d.month===10:id==='christmas'?d.month===12:false}
function seasonCurrent(id){const e=state.events?.[id];return !!e&&e.year===seasonDate().year}
function seasonProgress(id,i){const e=state.events?.[id],m=seasonMissions(id)[i];if(!e||!m)return 0;return seasonOpen(id)&&seasonCurrent(id)?Math.max(0,(state.stats[m.key]||0)-(e.baseline[m.key]||0)):(e.progress?.[i]||0)}
function recordSeasonProgress(){for(const id of SEASON_IDS){const e=state.events?.[id];if(e&&seasonOpen(id)&&seasonCurrent(id))e.progress=seasonMissions(id).map((m,i)=>seasonProgress(id,i))}}
function startChristmas(){if(!seasonOpen('christmas'))return false;if(seasonCurrent('christmas'))return false;state.events=state.events||{};state.events.christmas={year:seasonDate().year,baseline:{...state.stats},claimed:[],progress:[]};save();renderEvents();toast('🎄 ¡Navidad comenzó! Tus nuevas acciones cuentan para las misiones.');return true}
function claimChristmas(i){const e=state.events?.christmas,m=CHRISTMAS_MISSIONS[i];if(!seasonOpen('christmas')||!seasonCurrent('christmas')||!m||e.claimed.includes(i)||seasonProgress('christmas',i)<m.goal)return false;e.claimed.push(i);state.inventory.push({uid:uid(),id:'xm'+(i+1)});xp(20);save();render();toast('🎄 '+deco('xm'+(i+1)).name+' está en tu Almacén.');return true}
function startValentines(){if(!seasonOpen('valentines')||seasonCurrent('valentines'))return false;state.events=state.events||{};state.events.valentines={year:2027,baseline:{...state.stats},claimed:[],progress:[]};save();renderEvents();toast('💕 ¡Comienzan las misiones de enamorados!');return true}
function claimValentines(i){const e=state.events?.valentines,m=VALENTINE_MISSIONS[i];if(!seasonOpen('valentines')||!seasonCurrent('valentines')||!e||!m||e.claimed.includes(i)||seasonProgress('valentines',i)<m.goal)return false;e.claimed.push(i);state.inventory.push({uid:uid(),id:'vl'+(i+1)});xp(20);save();render();toast('💕 '+deco('vl'+(i+1)).name+' está en tu Almacén.');return true}
function halloweenState(){return state.events?.halloween||null}
function startHalloween(){if(!seasonOpen('halloween'))return false;if(seasonCurrent('halloween'))return false;if(halloweenState()?.fishClaimed&&!halloweenState().fishPlaced)return toast('Recibe primero tu pez desbloqueado de la temporada anterior.');state.events=state.events||{};state.events.halloween={year:seasonDate().year,progress:[],baseline:{...state.stats},claimed:[],fishClaimed:false,fishPlaced:false};save();renderEvents();toast('🎃 ¡Comienza Halloween! Tus nuevas acciones cuentan para las misiones.')}
function eventProgress(i){return seasonProgress('halloween',i)}
function claimHalloween(i){const e=halloweenState(),m=HALLOWEEN_MISSIONS[i];if(!seasonOpen('halloween')||!seasonCurrent('halloween')||!e||!m||e.claimed.includes(i)||eventProgress(i)<m.goal)return false;e.claimed.push(i);state.inventory.push({uid:uid(),id:'hw'+(i+1)});xp(20);save();render();toast('🎃 '+deco('hw'+(i+1)).name+' desbloqueado. Está en el Almacén.');return true}
function claimHalloweenFish(){const e=halloweenState();if(!seasonOpen('halloween')||!seasonCurrent('halloween')||!e||e.claimed.length!==10||e.fishClaimed)return false;e.fishClaimed=true;save();renderEvents();toast('🐟 Colmillo de Plata desbloqueado. Elige un acuario con espacio para recibirlo.');return true}
function placeHalloweenFish(){const e=halloweenState();if(!e?.fishClaimed||e.fishPlaced)return false;if(tank().fish.length>=capacity()){toast('Este acuario está lleno. Amplíalo o elige otro para recibir tu pez.');return false}tank().fish.push(fish('fang','Colmillo de Plata'));e.fishPlaced=true;save();render();toast('¡Colmillo de Plata llegó a tu acuario!');return true}
function renderEvents(){const host=$('eventBody');if(!host)return;host.replaceChildren();const active=SEASON_IDS.filter(id=>seasonOpen(id));$('eventAnchor').hidden=!active.length;if(!active.length)$('eventPanel').hidden=true;$('eventCount').textContent=active.length?SEASONS[active[0]].label:'Sin evento activo';for(const id of active){const hw=id==='halloween',open=seasonOpen(id),e=state.events?.[id],current=seasonCurrent(id),started=open&&current,missions=seasonMissions(id),prefix=SEASONS[id].prefix,label=SEASONS[id].label,icon=SEASONS[id].icon,dates=SEASONS[id].dates;const section=document.createElement('section');section.className='season-event '+id;section.innerHTML='<div class="event-banner"><span class="event-badge">'+(open?'ACTIVO':'FUERA DE TEMPORADA')+' · '+label.toUpperCase()+'</span><h2>'+icon+' '+SEASONS[id].title+'</h2><p>'+dates+' · horario de Ciudad de México.</p><p class="event-note">10 decoraciones por misiones'+(hw?' y un pez exclusivo':'')+'. Participa para iniciar el progreso. Los premios obtenidos se conservan todo el año.</p></div>';if(open&&!current){const start=document.createElement('button');start.textContent=icon+' Participar en '+label;start.id=hw?'startHalloween':id==='christmas'?'startChristmas':'startValentines';start.onclick=hw?startHalloween:id==='christmas'?startChristmas:startValentines;section.append(start)}const grid=document.createElement('div');grid.className='event-missions';missions.forEach((m,i)=>{const claimed=!!e?.claimed.includes(i),n=Math.min(m.goal,seasonProgress(id,i)),reward=deco(prefix+(i+1)),card=document.createElement('article');card.className='event-mission'+(claimed?' completed':'');card.innerHTML='<img src="'+reward.src+'" alt="'+reward.name+'" loading="lazy"><div><span class="event-badge">RECOMPENSA '+(i+1)+'</span><h3>'+m.title+'</h3><p>'+m.text+'</p><strong>'+reward.name+'</strong><label class="event-progress">Progreso '+n+'/'+m.goal+'<progress max="'+m.goal+'" value="'+n+'"></progress></label><button '+(!started||claimed||n<m.goal?'disabled':'')+'>'+(claimed?'✓ En tu colección':!open?'Disponible en '+(hw?'octubre':'diciembre'):!started?'Participa para comenzar':n>=m.goal?'Reclamar decoración':'Misión en curso')+'</button></div>';card.querySelector('button').onclick=()=>hw?claimHalloween(i):id==='christmas'?claimChristmas(i):claimValentines(i);grid.append(card)});section.append(grid);if(hw){const final=document.createElement('article');final.className='event-fish';final.innerHTML='<img src="assets/halloween-fish.png" alt="Colmillo de Plata"><div><span class="event-badge">PEZ EXCLUSIVO</span><h3>Colmillo de Plata</h3><p>Reclama las 10 decoraciones durante Halloween para desbloquear este pez. Si ya lo desbloqueaste, puedes recibirlo en cualquier fecha.</p><strong>'+(e?.claimed.length||0)+'/10 recompensas</strong><div><button id="claimEventFish" '+(!started||e?.fishClaimed||e?.claimed.length!==10?'disabled':'')+'>'+(e?.fishClaimed?'✓ Pez desbloqueado':'Desbloquear pez')+'</button>'+(e?.fishClaimed&&!e.fishPlaced?'<button id="placeEventFish">Recibir en este acuario</button>':'')+'</div></div>';section.append(final)}host.append(section)}if($('claimEventFish'))$('claimEventFish').onclick=claimHalloweenFish;if($('placeEventFish'))$('placeEventFish').onclick=placeHalloweenFish;}
function drawHalloweenFX(d,time,r){const id=d.id;if(!id.startsWith('hw'))return;ctx.save();ctx.translate(d.x*W,d.y*H);ctx.scale(d.flip?-1:1,1);if(id==='hw4'){ctx.fillStyle='rgba(166,255,64,'+(.2+Math.sin(time*3)*.1)+')';ctx.beginPath();ctx.ellipse(0,-r.h*.67,r.w*.22,r.h*.035,0,0,7);ctx.fill();for(let i=0;i<9;i++){const lift=(time*25+i*13)%110;ctx.strokeStyle='rgba(185,255,109,'+(1-lift/120)+')';ctx.lineWidth=1.4;ctx.beginPath();ctx.arc(Math.sin(time+i)*r.w*.09,-r.h*.65-lift*r.h/175,2+i%4,0,7);ctx.stroke()}}if(['hw1','hw2','hw3','hw7','hw9'].includes(id)){const positions=id==='hw1'?[[0,-.53]]:id==='hw9'?[[-.31,-.67],[.32,-.42]]:[[-.28,-.24],[.28,-.28]];for(const [x,y] of positions){const glow=ctx.createRadialGradient(x*r.w,y*r.h,0,x*r.w,y*r.h,r.w*.11);glow.addColorStop(0,'rgba(255,169,51,'+(.25+Math.sin(time*3+d.x)*.12)+')');glow.addColorStop(1,'rgba(255,130,30,0)');ctx.fillStyle=glow;ctx.fillRect((x-.12)*r.w,(y-.12)*r.h,r.w*.24,r.h*.24)}}if(['hw5','hw6','hw7','hw10'].includes(id)){for(let i=0;i<4;i++){const cycle=(time*.17+i*.25)%1;ctx.globalAlpha=Math.sin(cycle*Math.PI)*.65;ctx.fillStyle='#c8b5ff';ctx.beginPath();ctx.ellipse(Math.sin(time+i*2)*r.w*.3,-r.h*(.15+cycle*.85),r.w*.018,r.h*.05,Math.sin(time+i)*.4,0,7);ctx.fill()}}if(id==='hw8'){for(let i=0;i<2;i++){const x=Math.sin(time*.7+i*3)*r.w*.5,y=-r.h*(.65+Math.cos(time+i)*.12),wing=3+Math.sin(time*12)*3;ctx.fillStyle='#402951';ctx.beginPath();ctx.moveTo(x,y+2);ctx.lineTo(x-8,y-wing);ctx.lineTo(x-4,y+2);ctx.lineTo(x,y);ctx.lineTo(x+4,y+2);ctx.lineTo(x+8,y-wing);ctx.closePath();ctx.fill()}}ctx.restore()}

function drawChristmasFX(d,time,r){if(!d.id.startsWith('xm'))return;ctx.save();ctx.translate(d.x*W,d.y*H);ctx.scale(d.flip?-1:1,1);if(['xm1','xm3','xm8','xm9','xm10'].includes(d.id)){const y=d.id==='xm8'?-.48:-.78,g=ctx.createRadialGradient(0,y*r.h,0,0,y*r.h,r.w*.17);g.addColorStop(0,'rgba(255,237,155,'+(.25+Math.sin(time*2)*.1)+')');g.addColorStop(1,'#ffe6a000');ctx.fillStyle=g;ctx.fillRect(-r.w*.2,(y-.2)*r.h,r.w*.4,r.h*.4)}for(let i=0;i<5;i++){const phase=(time*.23+i*.19)%1;ctx.globalAlpha=Math.sin(phase*Math.PI)*.7;ctx.fillStyle=i%2?'#fff2b1':'#ddfaff';const x=Math.sin(i*7+d.x)*r.w*.35,y=-r.h*(.2+phase*.8),n=r.w*.009;ctx.fillRect(x-n,y,n*2,n*.4);ctx.fillRect(x-n*.2,y-n*.8,n*.4,n*2)}ctx.restore()}
