function paintTankLight(c,w,h,t,time){const l=tankLight(t);if(!l.enabled||!l.intensity)return;if(t.waterMotion===false||reducedWaterMotion?.matches)time=0;c.save();c.globalCompositeOperation='screen';const rgb=l.color.match(/\w\w/g).map(x=>parseInt(x,16)).join(',');for(let i=0;i<3;i++){const x=w*(.18+i*.32),g=c.createRadialGradient(x,0,0,x,h*.15,h*.9);g.addColorStop(0,'rgba('+rgb+','+(l.intensity*.65)+')');g.addColorStop(1,'rgba('+rgb+',0)');c.fillStyle=g;c.fillRect(0,0,w,h);c.fillStyle='rgba('+rgb+','+(l.intensity*.13)+')';c.beginPath();c.moveTo(x-12,0);c.lineTo(x+12,0);c.lineTo(x+h*.25+Math.sin(time*.3+i)*15,h);c.lineTo(x-h*.25,h);c.fill()}c.globalAlpha=.7;c.fillStyle=l.color;c.shadowColor=l.color;c.shadowBlur=16;c.fillRect(0,0,w,4);c.restore()}
