for(let i=0;i<7;i++){b.fillStyle='#dfffff0c';b.beginPath();b.moveTo(w*i/6-w*.08,0);b.lineTo(w*i/6+w*.05,0);b.lineTo(w*i/6+w*.2,h);b.lineTo(w*i/6-w*.02,h);b.fill()}
