if(scene.landscape==='river'){b.strokeStyle='#203e3650';b.lineWidth=w*.02;for(let i=0;i<3;i++){const x=w*(.05+i*.43);b.beginPath();b.moveTo(x,0);b.bezierCurveTo(x+w*.08,h*.18,x-w*.06,h*.34,x+w*.02,h*.6);b.stroke()}}
