let camera={zoom:1,x:.5,y:.5};
function worldFactor(t=tank()){return 1+t.size*.25}
function viewPoint(px,py,width,height){return{x:(px/width-.5)/camera.zoom+camera.x,y:(py/height-.5)/camera.zoom+camera.y}}
function renderTankSpace(){const size=tank().size;$('canvas').style.width='100%';$('tank').style.aspectRatio='auto';$('tank').style.height='clamp(290px, 48vw, 510px)';$('tankSpace').textContent='Tamaño '+(size+1)+'/5 · '+(camera.zoom===1?'Vista completa':'Vista cercana')+' · '+capacity()+' peces';$('tankPan').hidden=false;$('tankZoom').textContent=camera.zoom===1?'＋ Acercar':'− Alejar';$('tankLeft').disabled=$('tankRight').disabled=$('tankUp').disabled=$('tankDown').disabled=camera.zoom===1;}
function moveCamera(dx,dy){const edge=.5/camera.zoom;camera.x=Math.max(edge,Math.min(1-edge,camera.x+dx/camera.zoom));camera.y=Math.max(edge,Math.min(1-edge,camera.y+dy/camera.zoom));}


function normalizeSave(s){if(!s||!Array.isArray(s.tanks)||!Array.isArray(s.inventory))return s;for(const id of SEASON_IDS)if(s.events?.[id]){const e=s.events[id];if(!e.baseline||typeof e.baseline!=='object'||!Array.isArray(e.claimed))delete s.events[id];else{e.claimed=[...new Set(e.claimed.filter(i=>Number.isInteger(i)&&i>=0&&i<10))];e.year=Number.isInteger(e.year)?e.year:2026;e.progress=Array.isArray(e.progress)?e.progress.map(n=>Number.isFinite(n)?Math.max(0,n):0):[];e.fishClaimed=!!e.fishClaimed;e.fishPlaced=!!e.fishPlaced}}s.substrates=Array.isArray(s.substrates)?[...new Set(['sand',...s.substrates.filter(id=>SUBSTRATES.some(x=>x.id===id))])]:['sand'];for(const t of s.tanks){if(!s.substrates.includes(t.substrate))t.substrate='sand';t.theme=tankTheme(t);t.waterMotion=t.waterMotion!==false;t.light=tankLight(t);t.name=t.name?.slice(0,28)||'Mi arrecife'}const remap={chest:'ship',purple:'coral',grass:'plant',anemone:'coral',star:'shell',mushroom:'coral',anchor:'ship',pebbles:'rock',fan:'coral',tube:'coral',lily:'shell',crystal:'arch'};for(const t of s.tanks){if(Array.isArray(t.decor))for(const d of t.decor)d.id=remap[d.id]||d.id;}for(const d of s.inventory)d.id=remap[d.id]||d.id;if(s.stats){for(const key of ['foodBought','dailyClaims','sold','expanded'])if(!Number.isFinite(s.stats[key]))s.stats[key]=0;}return s;}
function valid(s){return s&&s.version===1&&Number.isFinite(s.coins)&&s.coins>=0&&Number.isFinite(s.xp)&&Number.isFinite(s.food)&&Array.isArray(s.tanks)&&s.tanks.length>0&&s.tanks.length<=5&&Number.isInteger(s.active)&&s.active>=0&&s.active<s.tanks.length&&Array.isArray(s.inventory)&&s.inventory.every(i=>deco(i.id))&&Array.isArray(s.claimed)&&s.stats&&Number.isFinite(s.last)&&s.tanks.every(t=>typeof t.name==='string'&&Number.isFinite(t.clean)&&Number.isFinite(t.bank)&&Number.isInteger(t.size)&&t.size>=0&&t.size<=4&&Array.isArray(t.decor)&&t.decor.every(d=>deco(d.id)&&Number.isFinite(d.x)&&Number.isFinite(d.y))&&Array.isArray(t.fish)&&t.fish.every(f=>species(f.species)&&typeof f.name==='string'&&['age','hunger','x','y','cooldown','trained'].every(k=>Number.isFinite(f[k]))))}
const tank=()=>state.tanks[state.active],level=()=>1+Math.floor(Math.sqrt(state.xp/55)),capacity=(t=tank())=>8+t.size*10;
function simulate(seconds){if(typeof gamePaused!=='undefined'&&gamePaused)return;seconds=Math.max(0,Math.min(seconds,28800));state.tanks.forEach(t=>{const before=t.clean;t.clean=Math.max(15,t.clean-seconds*.018);t.fish.forEach(f=>{const s=species(f.species),productive=Math.max(0,Math.min(seconds,(f.hunger-20)/.055,(before-35)/.018));if(productive>0){f.age=Math.min(s.grow,f.age+productive);t.bank=Math.min(5000,t.bank+productive*s.rate/25*(1+f.trained*.12))}f.hunger=Math.max(0,f.hunger-seconds*.055);f.cooldown=Math.max(0,f.cooldown-seconds)})})}
