window.aquariumGame={snapshot:()=>JSON.parse(JSON.stringify(state)),fresh:()=>normalizeSave(initial()),validate:s=>{try{return !!valid(normalizeSave(JSON.parse(JSON.stringify(s))))}catch{return false}},storage:k=>{storageKey=k},pause:on=>{gamePaused=on;if(on){setFeeding(false);if(trainingTimer){clearInterval(trainingTimer);trainingTimer=null}$('dialog').close()}},replace:incoming=>{incoming=normalizeSave(JSON.parse(JSON.stringify(incoming)));if(!valid(incoming))throw Error('invalid_save');state=incoming;pointers.clear();gesture=null;drag=null;camera={zoom:1,x:.5,y:.5};const paused=gamePaused;gamePaused=false;simulate((Date.now()-state.last)/1000);gamePaused=paused;particles=[];placing=null;editing=false;decorSelected=null;$('placement').style.display='none';$('edit').style.background='';render()},save};
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),3300)}
function xp(n){const old=level();state.xp+=n;if(level()>old)toast('✦ ¡Nivel '+level()+'! Nuevos amigos te esperan.')}function pay(n){if(state.coins<n){toast('Te faltan monedas. Recolecta las de tus peces.');return false}state.coins-=n;return true}
function fishSVG(s){return '<img class="fish-sprite" src="'+FISH_ASSETS[s.id].src+'" alt="'+s.name+'">'}
function fishImage(s){const key='sprite-'+s.id;if(!artCache.has(key)){const im=new Image();im.src=FISH_ASSETS[s.id].src;artCache.set(key,im)}return artCache.get(key)}
function drawSwimmingFish(im,size,time,index,chasing){if(!im.complete||!im.naturalWidth)return;const iw=im.naturalWidth,ih=im.naturalHeight,h=size*ih/iw,beat=time*(chasing?10:6)+index*1.7;const slices=40;for(let n=0;n<slices;n++){const u=n/slices,sw=iw/slices,tail=Math.pow(1-u,2),offset=Math.sin(beat+u*3.5)*size*.038*tail;ctx.drawImage(im,n*sw,0,sw,ih,-size/2+n*size/slices,-h/2+offset,size/slices+.35,h*(1+Math.sin(beat)*tail*.018));}}
function decorSVG(d){return '<img class="decor-sprite" src="'+d.src+'" alt="'+d.name+'">'}
function decorImage(d){const key='decor-'+d.id;if(!artCache.has(key)){const im=new Image();im.src=d.src;artCache.set(key,im)}return artCache.get(key)}
const artCache=new Map();function art(key,svg){if(!artCache.has(key)){const i=new Image();i.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);artCache.set(key,i)}return artCache.get(key)}
function render(){renderTankSpace();const t=tank();$('coins').textContent=Math.floor(state.coins).toLocaleString('es-MX');$('level').textContent=level();$('clean').textContent=Math.round(t.clean);$('capacity').textContent=t.fish.length+' / '+capacity();$('food').textContent=state.food+' porciones';$('income').textContent=Math.floor(t.bank)+' disponibles';$('upgradePrice').textContent=t.size>=4?'Tamaño máximo':(300*(t.size+1))+' monedas';$('tankLabel').textContent=t.name.toUpperCase();$('tankTabs').replaceChildren();state.tanks.forEach((t,i)=>{const b=document.createElement('button');b.textContent=t.name;b.className=i===state.active?'active':'';b.title=i===state.active?'Editar nombre, fondo e iluminación':'Cambiar a este acuario';b.onclick=()=>{if(i===state.active){closeAquariumPanels();personalizeTank();return}closeAquariumPanels();setFeeding(false);particles=[];state.active=i;camera={zoom:1,x:.5,y:.5};placing=null;editing=false;$('placement').style.display='none';render();save()};$('tankTabs').append(b)});$('daily').textContent=dailyReady()?'🗝 Tesoro disponible':'✓ Tesoro recogido';$('treasure').setAttribute('aria-label',dailyReady()?'Abrir cofre: 200 monedas y 25 comidas gratis':'Cofre diario recogido; vuelve mañana');$('treasure').classList.toggle('ready',dailyReady());$('treasure').classList.toggle('opened',!dailyReady());renderQuest();renderShop();renderDecorEditor();renderEvents()}
function renderShop(){if(tab==='substrate'){renderSubstrateShop();return;}if(tab==='food'){renderFoodShop();return;}document.querySelectorAll('#shopTabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('shopTitle').textContent={fish:'Pequeños nuevos amigos',decor:'Un hogar con personalidad',inventory:'Tu almacén'}[tab];$('shopSubtitle').textContent={fish:'Cría, cuida y descubre las '+SPECIES.filter(s=>!s.event).length+' especies.',decor:'Compra y coloca cada pieza en la arena.',inventory:'Decoraciones guardadas, listas para usar.'}[tab];$('shop').replaceChildren();const items=tab==='fish'?SPECIES.filter(x=>!x.event):tab==='decor'?DECOR.filter(x=>!x.event):state.inventory.map(i=>({...deco(i.id),inventoryUid:i.uid}));if(tab==='inventory'&&!items.length&&!(halloweenState()?.fishClaimed&&!halloweenState().fishPlaced)){const p=document.createElement('p');p.className='empty';p.textContent='Tu almacén está vacío. Compra decoraciones o guarda las que tienes en el acuario.';$('shop').append(p)}if(tab==='inventory'&&halloweenState()?.fishClaimed&&!halloweenState().fishPlaced){const reward=document.createElement('div');reward.className='card';reward.innerHTML='<div class="art"><img class="fish-sprite" src="assets/halloween-fish.png" alt="Colmillo de Plata"></div><div><h3>Colmillo de Plata</h3><p>Tu premio desbloqueado</p><button>Recibir en este acuario</button></div>';reward.querySelector('button').onclick=placeHalloweenFish;$('shop').append(reward)}items.forEach(s=>{const locked=tab==='fish'&&level()<s.level;const card=document.createElement('div');card.className='card';card.innerHTML=`<div class="art">${tab==='fish'?fishSVG(s):decorSVG(s)}</div><div><span class="rarity">${tab==='fish'?s.rarity:tab==='inventory'?'EN EL ALMACÉN':'DECORACIÓN'}</span><h3>${s.name}</h3><p>${tab==='fish'?s.rate+' monedas / 25 s · '+Math.ceil(s.grow/60)+' min':tab==='inventory'?'Listo para colocar':'Diseño original'}</p><button ${locked?'disabled':''}>${locked?'🔒 Nivel '+s.level:tab==='inventory'?'Colocar →':'🪙 '+s.price+' · Comprar'}</button></div>`;card.querySelector('button').onclick=()=>{if(tab==='fish'){if(tank().fish.length>=capacity())return toast('Tu acuario está lleno. Amplíalo o crea otro.');if(pay(s.price)){tank().fish.push(fish(s.id));state.stats.bought++;xp(15);toast(s.name+' se une a tu acuario');save();render()}}else if(tab==='decor'){if(pay(s.price)){const i={uid:uid(),id:s.id};state.inventory.push(i);startPlace(i);save();renderShop();$('coins').textContent=state.coins}}else startPlace({uid:s.inventoryUid,id:s.id})};$('shop').append(card)})}
