document.addEventListener('keydown',e=>{if(e.key==='Escape')setFeeding(false)});
$('scrub').onclick=()=>{if(tank().clean>=99)return toast('El agua ya está cristalina.');tank().clean=100;state.stats.cleaned++;xp(12);toast('🫧 Agua limpia y peces contentos.');save();render()};
$('collect').onclick=()=>{const n=Math.floor(tank().bank);if(n<1)return toast('Tus peces generan monedas cuando están alimentados y el agua está limpia.');tank().bank-=n;state.coins+=n;state.stats.collected++;xp(5);toast('+'+n+' monedas para tu colección');save();render()};
$('edit').onclick=()=>{setFeeding(false);editing=!editing;placing=null;$('placement').style.display='none';toast(editing?'Arrastra las decoraciones. Selecciona una para ajustar tamaño, reflejo y capas.':'Decoración terminada.');$('edit').style.background=editing?'#e0edcf':'';renderDecorEditor()};
$('upgrade').onclick=expandTank;
