canvas.addEventListener('wheel',e=>{e.preventDefault();if(pointers.size)return;const r=canvas.getBoundingClientRect(),delta=e.deltaY*(e.deltaMode===1?16:e.deltaMode===2?r.height:1);cameraZoomAt(camera.zoom*Math.exp(-Math.max(-300,Math.min(300,delta))*.002),e.clientX-r.left,e.clientY-r.top,r.width,r.height)},{passive:false});
canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button!==0&&e.button!==1)return;if(pointers.size>=2)return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,moved:false,blocked:e.button===1,middle:e.button===1});canvas.setPointerCapture(e.pointerId);if(pointers.size===2){beginPinch();return}if(gamePaused)return;const q=coords(e);if(editing&&!feeding&&!placing){const d=orderedDecor().reverse().find(d=>{const r=decorBounds(d);return q.x*W>=r.x&&q.x*W<=r.x+r.w&&q.y*H>=r.y&&q.y*H<=r.y+r.h});if(d){decorSelected=d.uid;renderDecorEditor();drag={d,start:q,moved:false,origin:{x:d.x,y:d.y}}}}});
canvas.addEventListener('pointermove',e=>{const p=pointers.get(e.pointerId),q=coords(e);if(feeding)bottle={...bottle,...q,visible:true};if(!p)return;const dx=e.clientX-p.x,dy=e.clientY-p.y;p.x=e.clientX;p.y=e.clientY;if(Math.hypot(p.x-p.startX,p.y-p.startY)>7)p.moved=true;if(pointers.size===2&&gesture){const pair=pointerPair(),r=canvas.getBoundingClientRect();camera.zoom=Math.max(1,Math.min(3,gesture.zoom*pair.d/gesture.d));camera.x=gesture.anchor.x-((pair.x-r.left)/r.width-.5)/camera.zoom;camera.y=gesture.anchor.y-((pair.y-r.top)/r.height-.5)/camera.zoom;clampCamera();renderTankSpace();return}if(p.blocked&&!p.middle)return;if(drag){if(p.moved)drag.moved=true;if(drag.moved){drag.d.x=Math.max(.05,Math.min(.95,drag.origin.x+q.x-drag.start.x));drag.d.y=Math.max(.5,Math.min(.96,drag.origin.y+q.y-drag.start.y))}return}if(p.moved&&camera.zoom>1&&(p.middle||(!feeding&&!placing))){const r=canvas.getBoundingClientRect();moveCamera(-dx/r.width,-dy/r.height);canvas.classList.add('camera-dragging')}});
function endPointer(e,canceled=false){const p=pointers.get(e.pointerId);if(!p)return;const wasPinch=!!gesture;if(drag){if(canceled){drag.d.x=drag.origin.x;drag.d.y=drag.origin.y}drag=null;save();renderDecorEditor()}pointers.delete(e.pointerId);if(pointers.size<2)gesture=null;if(!pointers.size)canvas.classList.remove('camera-dragging');if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);if(!canceled&&!wasPinch&&!p.blocked&&!p.moved)aquariumTap(e)}
canvas.addEventListener('pointerup',e=>endPointer(e));canvas.addEventListener('pointercancel',e=>endPointer(e,true));canvas.addEventListener('lostpointercapture',e=>{if(pointers.has(e.pointerId))endPointer(e,true)});canvas.addEventListener('pointerleave',()=>{bottle.visible=false});
setInterval(()=>{simulate(1);const day=seasonDate(),key=day.year+'-'+day.month+'-'+day.day;if(renderEvents.day!==key){renderEvents.day=key;renderEvents()}$('clean').textContent=Math.round(tank().clean);$('income').textContent=Math.floor(tank().bank)+' disponibles'},1000);setInterval(save,10000);window.addEventListener('pagehide',save);render();save();requestAnimationFrame(draw);



window.aquariumGame.reserve=()=> (state.expeditionFish||[]).filter(r=>['fang','royal'].includes(r.species)).map(r=>({...r,name:species(r.species).name,src:FISH_ASSETS[r.species].src}));
window.aquariumGame.receiveFish=(id,index)=>{if(gamePaused||!Number.isInteger(index)||!state.tanks[index])return false;const t=state.tanks[index],i=(state.expeditionFish||[]).findIndex(r=>r.id===id&&['fang','royal'].includes(r.species));if(i<0)return false;if(t.fish.length>=capacity(t)){toast('Ese acuario está lleno. Tu pez sigue seguro en la reserva.');return false}const r=state.expeditionFish.splice(i,1)[0];t.fish.push(fish(r.species));save();render();toast('¡Tu pez de expedición llegó al acuario!');return true};
// Vista independiente: jamás sustituye la partida propia ni ejecuta sus controles.
window.aquariumGame.drawVisit=(surface,incoming,time)=>{
 const c=surface.getContext('2d'),w=surface.width,h=surface.height;
 const number=(x,d=0)=>Number.isFinite(Number(x))?Number(x):d;
 const clamp=(x,a,b,d=a)=>Math.max(a,Math.min(b,number(x,d)));
 paintTankBackground(c,w,h,incoming);
 paintSubstrate(c,w,h,incoming);
 paintWaterMotion(c,w,h,incoming,time);
 (Array.isArray(incoming.decor)?incoming.decor:[]).slice(0,100).filter(d=>deco(d.id)).sort((a,b)=>number(a.layer)-number(b.layer)).forEach(d=>{const s=deco(d.id),im=decorImage(s),size=Math.min(w*.23,175)*clamp(d.scale,.4,2,1)/(1+clamp(incoming.size,0,4)*.25);c.save();c.translate(clamp(d.x,0,1)*w,clamp(d.y,0,1)*h);c.scale(d.flip?-1:1,1);if(['coral','hw3','hw9'].includes(s.id))c.transform(1,0,Math.sin(time)*.018,1,0,0);if(im.complete&&im.naturalWidth)c.drawImage(im,-size*Math.min(1,s.aspect||1)/2,-size*Math.min(1,1/(s.aspect||1)),size*Math.min(1,s.aspect||1),size*Math.min(1,1/(s.aspect||1)));if(['volcano','hw4'].includes(s.id)){c.strokeStyle=s.id==='hw4'?'#c3ff99':'#deffff';for(let j=0;j<5;j++){c.beginPath();c.arc(Math.sin(time+j)*8,-size*.7-(time*20+j*16)%90,2+j%3,0,7);c.stroke()}}c.restore()});
 (Array.isArray(incoming.fish)?incoming.fish:[]).slice(0,48).filter(f=>species(f.species)).forEach((f,i)=>{const s=species(f.species),im=fishImage(s),size=(s.displayScale||1)*Math.min(w*.15,115)*(.55+.45*clamp(number(f.age)/s.grow,0,1))/(1+clamp(incoming.size,0,4)*.25),x=(clamp(f.x,.1,.9)*w+Math.sin(time*.2+i)*w*.04),y=clamp(f.y,.12,.75)*h+Math.sin(time+i)*h*.02;c.save();c.translate(x,y);c.scale(f.dir===-1?-1:1,1);if(im.complete&&im.naturalWidth){const ih=size*im.naturalHeight/im.naturalWidth;for(let n=0;n<32;n++){const u=n/32;c.drawImage(im,n*im.naturalWidth/32,0,im.naturalWidth/32,im.naturalHeight,-size/2+n*size/32,-ih/2+Math.sin(time*6+u*3.5+i)*size*.035*(1-u)**2,size/32+.4,ih)}}c.restore()});
 for(let i=0;i<15;i++){c.strokeStyle='#d7ffff60';c.beginPath();c.arc((i*97.3)%w,h-(time*(12+i%4*5)+i*39)%h,2+i%4,0,7);c.stroke()}
 paintTankLight(c,w,h,incoming,time);
};

window.aquariumGame.guidance={ready:()=>!gamePaused,key:()=>storageKey,observing:()=>observing,read:()=>JSON.parse(JSON.stringify(state.guidance||{})),isNew:()=>state.xp===0&&(state.stats.fed||0)===0&&(state.stats.bought||0)===0,mark:(key)=>{if(gamePaused)return;state.guidance=state.guidance&&typeof state.guidance==='object'?state.guidance:{};state.guidance[key]=true;save()},season:()=>SEASON_IDS.find(id=>seasonOpen(id))||null,year:()=>seasonDate().year};

function drawValentineFX(d,time,r){if(!d.id.startsWith('vl'))return;ctx.save();ctx.translate(d.x*W,d.y*H);ctx.scale(d.flip?-1:1,1);for(let i=0;i<3;i++){const phase=(time*.15+i/3)%1;ctx.globalAlpha=Math.sin(phase*Math.PI)*.5;const x=Math.sin(i*4+d.x)*r.w*.28,y=-r.h*(.3+phase*.65),n=r.w*.025;ctx.fillStyle='#ffc4d7';ctx.beginPath();ctx.moveTo(x,y+n);ctx.bezierCurveTo(x-n*2,y-n,x-n,y-n*2,x,y-n);ctx.bezierCurveTo(x+n,y-n*2,x+n*2,y-n,x,y+n);ctx.fill()}ctx.restore()}
